export default async function (ctx) {
    
  const fixName = (n) => {
    const name = n || ""; 
    if (name.trim() === "") return "SubInfo";
    return name;
  };

  function formatBytes(bytes, hideDecimal = false) {
    if (!bytes || bytes === 0) return "0B";
    const k = 1024;
    const sizes = ["B", "K", "M", "G", "T", "P"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    const val = bytes / Math.pow(k, i);
    return hideDecimal ? `${Math.floor(val)}${sizes[i]}` : `${val.toFixed(2)}${sizes[i]}`;
  }

  async function getSubData(url, name, isTripleMode) {
    let data = { name: fixName(name), usage: "0.00M/0G", date: "无到期信息", percent: "0%" };
    if (!url || typeof url !== 'string' || !url.trim().startsWith("http")) return data;
    try {
      const resp = await ctx.http.get(url, { headers: { "User-Agent": "Quantumult%20X/1.5.2" }, timeout: 4000 });
      const infoHeader = resp.headers["subscription-userinfo"] || "";
      const info = Object.fromEntries(infoHeader.match(/\w+=[\d.eE+-]+/g)?.map(p => p.split("=").map(v => isNaN(v) ? v : Number(v))) || []);
      if (info.total) {
        const used = (info.upload || 0) + (info.download || 0);
        data.usage = `${formatBytes(used)}/${formatBytes(info.total, isTripleMode)}`;
        data.percent = `${Math.min(100, Math.round((used / info.total) * 100))}%`;
      }
      if (info.expire) {
        const d = new Date(info.expire * 1000);
        data.date = `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')}`;
      }
    } catch (e) { data.usage = "连接超时"; }
    return data;
  }

  const GLOBAL_TXT_COLOR = ctx.env.TEXT_COLOR || "#000000";
  const WIDGET_BG = ctx.env.WIDGET_BG || "#FFFFFF";
 
  const ICON_SIZE = ctx.env.ICON_SIZE ? Number(ctx.env.ICON_SIZE) : null;

  const STYLES = [
    { color: ctx.env.BG1 || "#FFFFE3", symbol: "filemenu.and.selection", textColor: ctx.env.COLOR1 || GLOBAL_TXT_COLOR },           
    { color: ctx.env.BG2 || "#F9FFF2", symbol: "checkerboard.rectangle", textColor: ctx.env.COLOR2 || GLOBAL_TXT_COLOR },              
    { color: ctx.env.BG3 || "#D6F6FF", symbol: "list.bullet.rectangle", textColor: ctx.env.COLOR3 || GLOBAL_TXT_COLOR } 
  ];

  const envs = [{ url: ctx.env.URL1, name: ctx.env.NAME1 }, { url: ctx.env.URL2, name: ctx.env.NAME2 }, { url: ctx.env.URL3, name: ctx.env.NAME3 }];
  const activeIndices = [];
  envs.forEach((env, i) => { if (env.url && typeof env.url === 'string' && env.url.trim().startsWith("http")) activeIndices.push(i); });

  const isTripleMode = activeIndices.length === 3;
  let CARD_WIDTH = isTripleMode ? 104 : 151; 

  function buildRect(style, data) {
    const TXT = style.textColor;
    return {
      type: "stack", direction: "column", width: CARD_WIDTH, flex: 1,
      backgroundColor: style.color, borderRadius: 18, padding: 10, alignItems: "start",
      children: [
        {
          type: "stack", direction: "row", alignItems: "center",
          children: [
            {
              type: "stack", width: 30, height: 30, backgroundColor: TXT, borderRadius: 15,
              alignItems: "center", justifyContent: "center",
              children: [{ type: "image", src: `sf-symbol:${style.symbol}`, width: 16, height: 16, color: style.color }]
            },
            { type: "spacer" },
            {
              type: "stack", width: 30, height: 30, borderRadius: 15, borderWidth: 1, borderColor: TXT,
              alignItems: "center", justifyContent: "center",
              children: [{ type: "text", text: data.percent, font: { size: 9, weight: "bold" }, textColor: TXT }]
            }
          ]
        },
        { type: "spacer", length: 14 },
        {
          type: "stack", direction: "column", alignItems: "start", gap: 7, padding: 0,
          children: [
            { type: "text", text: data.name, font: { size: 15, weight: "bold" }, textColor: TXT, maxLines: 1 },
            { type: "text", text: data.usage, font: { size: 13, weight: "medium" }, textColor: TXT, maxLines: 1 },
            { type: "text", text: data.date, font: { size: 11 }, textColor: TXT, maxLines: 1 }
          ]
        },
        { type: "spacer" }
      ]
    };
  }

//======================================

//##############图片#######SF############

//--------------------------------------

  function buildEmptyRectWithIcon() {
    const rawIcon = ctx.env.EMPTY_ICON || ""; 
    let iconContent = (rawIcon !== "" && rawIcon !== "未设置") ? rawIcon : "data:image/jpeg;base64,";

//--------------------------------------

//##############图片#####SF###############

//=======================================
       let finalSrc = iconContent.startsWith("data:image") ? iconContent : `sf-symbol:${iconContent}`;
    
    return {
      type: "stack", 
      direction: "column", 
      width: CARD_WIDTH, 
      flex: 1,   
      backgroundColor: ctx.env.EMPTY_BG || "#FFFFFF", 
      borderRadius: 18,
      padding: 0,   
      alignItems: "center",
      justifyContent: "center",
      children: [{ 
        type: "image", 
        src: finalSrc, 
        width: ICON_SIZE || CARD_WIDTH,        
        flex: 1,
        resizeMode: "cover", 
        resizable: true,     
        borderRadius: 18,
        color: iconContent.startsWith("data:image") ? undefined : (ctx.env.EMPTY_ICON_COLOR || "#000000")
      }]
    };
  }

  let finalChildren = [];
  try {
    if (activeIndices.length === 0) {
      finalChildren = [buildEmptyRectWithIcon(), buildEmptyRectWithIcon()];
    } else if (activeIndices.length === 1) {
      const data = await getSubData(envs[activeIndices[0]].url, envs[activeIndices[0]].name, false);
      const dataRect = buildRect(STYLES[activeIndices[0]], data);
      const iconRect = buildEmptyRectWithIcon();
      finalChildren = (ctx.env.SWAP_POS === "true") ? [iconRect, dataRect] : [dataRect, iconRect];
    } else {
      finalChildren = await Promise.all(activeIndices.map(async (i) => buildRect(STYLES[i], await getSubData(envs[i].url, envs[i].name, isTripleMode))));
    }
  } catch (err) {
   
    return { type: "widget", children: [{ type: "text", text: "渲染失败: " + err.message }] };
  }

  return {
    type: "widget",
    backgroundColor: WIDGET_BG,
    padding: 12, 
    children: [{
      type: "stack",
      direction: "row",
      flex: 1, 
      gap: 12, 
      children: finalChildren
    }]
  };
}
